from taf.rfrl.procedures.resources.python.parser.xml_parser import XmlFile
from taf.rfrl.procedures.resources.python.log_verifiers.exceptions import XmlElementNotFoundError, ResponsesNotEqualRequestsError

from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output, log_result,
)


def check_if_ecipri_msg5_delay_measurement_msg_exists(xml_file_path):
    """
    Checks if xml file contains a specific element with a specific tag and specific parameters names and values.
    Element to search for:
    <managedObject distName="supportedFeature41" class="SupportedFeature">
          <parameter>
            <parameterName>feature</parameterName>
            <newValue>ECPRI_MSG5_DELAY_MEASUREMENT</newValue>
            <prevValue/>
          </parameter>
          <parameter>
            <parameterName>support</parameterName>
            <newValue>9</newValue>
            <prevValue/>
          </parameter>
    </managedObject>

    :param xml_file_path: Absolute path to XML file e.g. "/home/ute/Desktop/CRT_Test/TEST/file.xml"
    :type xml_file_path: str
    :return: True if the element found, otherwise raises .
    :rtype: bool
    """
    xml_file = XmlFile(xml_file_path)
    main_tag = ".//managedObject[@class='SupportedFeature']"
    searched_parameters = [{"tag": "parameter", "parameter_content": [{"tag": "parameterName", "text": "feature"},
                                                                      {"tag": "newValue", "text": "ECPRI_MSG5_DELAY_MEASUREMENT"}]},
                           {"tag": "parameter", "parameter_content": [{"tag": "parameterName", "text": "support"},
                                                                      {"tag": "newValue", "text": 9}]}]

    matched_elements = xml_file.get_custom_elements_children_and_grandchildren(custom_element_name=main_tag, xpath=True)
    found_elements = _match_elements_by_content(elements=matched_elements, searched_content=searched_parameters)

    if not found_elements:
        raise XmlElementNotFoundError('Could not find element: <managedObject distName="supportedFeature41" class="SupportedFeature"> '
                                      'with parameters:\n'
                                      '1) <parameterName>feature</parameterName> <newValue>ECPRI_MSG5_DELAY_MEASUREMENT</newValue> \n'
                                      '2) <parameterName>support</parameterName> <newValue>9</newValue>')


@log_input_and_output
def verify_ecipri_delay_measurement_ruquests_equal_responses(xml_file_path):
    """
    Verifies whether an "ECpriDelayMeasurementSession" request has been created at least once and
    ensures that all found requests have a corresponding response with proper status.

    Example XML request structure:
    <managedObject class="ECpriDelayMeasurementSession" distName="BTS9266.eCpriDelayMeasurementSession_3221225472">
          <operation>create_mo</operation>
          <parameter>
            <parameterName>transportLink</parameterName>
            <newValue>BTS9266.ethernetLink_2874f5099e79_1_0</newValue>
            <prevValue/>
          </parameter>
    </managedObject>

    Example correct XML response structure:
    <managedObject distName="BTS9266.eCpriDelayMeasurementSession_3221225472" class="ECpriDelayMeasurementSession">
      <operation>create_mo</operation>
      <parameter>
        <parameterName>subscribe</parameterName>
        <newValue>TRUE</newValue>
        <prevValue/>
      </parameter>
      <parameter>
        <parameterName>transportLink</parameterName>
        <newValue>BTS9266.ethernetLink_2874f5099e79_1_1</newValue>
        <prevValue/>
      </parameter>
    </managedObject>

    :param xml_file_path: Absolute path to XML file e.g "/home/ute/Desktop/CRT_Test/TEST/file.xml"
    :type xml_file_path: str
    :raises XmlElementNotFoundError: Raised when the ECpriDelayMeasurementSession request is not found in the XML file.
    :raises ResponsesNotEqualRequestsError: Raised when the response does not match the request or has an invalid confirmation status.
    """

    xml_file = XmlFile(xml_file_path)
    main_tag = './/managedObject[@class="ECpriDelayMeasurementSession"]'
    matched_elements_by_main_tag = xml_file.get_custom_elements_children_and_grandchildren(custom_element_name=main_tag, xpath=True)

    searched_parameters = [{"tag": "operation", "text": "create_mo"}]
    requests_and_responses_msgs = _match_elements_by_content(elements=matched_elements_by_main_tag, searched_content=searched_parameters)

    requests = [e for e in requests_and_responses_msgs if "subscribe" not in str(e)]
    responses = [e for e in requests_and_responses_msgs if e not in requests]
    log_result(f"All requests:\n{requests}\n All responses:\n{responses}")

    if not requests:
        raise XmlElementNotFoundError("ECpriDelayMeasurementSession request not found in the XML file.")

    not_found = []
    for request in requests:
        found_response = False
        for response in responses:
            if request['attributes']['distName'] == response['attributes']['distName']:
                found_response = True
                if not XmlFile.check_element_content(
                        element=response, searched_content={"tag": "parameter", 'parameter_content': [{"tag": "newValue", "text": "TRUE"}]}):
                    parameter_content = [child['parameter_content'] for child in response[f'{response["tag"]}_content'] if child['tag'] == 'parameter'
                                         and 'subscribe' in str(child['parameter_content'])]
                    not_found.append((request['attributes']['distName'], f"Invalid response confirmation: response: {parameter_content}"))

                responses.remove(response)
                break

        if not found_response:
            not_found.append((request['attributes']['distName'], "No response found"))

    if not_found:
        raise ResponsesNotEqualRequestsError(f"Following requests have no corresponding or invalid response: {not_found}")


@log_input_and_output
def _match_elements_by_content(elements, searched_content):
    """
    Matches elements by content.

    :param elements: List of elements found by the `get_custom_elements_children_and_grandchildren` method from the XmlFile class.
    :type elements: list[dict]
    :return: The matched elements.
    :rtype: list
    """
    return [element for element in elements if XmlFile.check_element_content(element, searched_content.copy())]
